-- HG Industries: the simulation's output, ksl_db, added to the book's database.
--
-- GENERATED by scripts/build-add-k.py from the database the simulation wrote;
-- do not edit. Run it in the database loaded with through-q.sql, when you
-- cannot run the companion program dbconcepts.simulation.RunFrameLineKt. It
-- deletes any ksl_db schema and creates it as the simulation would, with the
-- same statistics, since the model's random number streams are fixed.

DROP SCHEMA IF EXISTS ksl_db CASCADE;

CREATE SCHEMA ksl_db;




--
-- Name: across_rep_stat; Type: TABLE; Schema: ksl_db; Owner: -
--

CREATE TABLE ksl_db.across_rep_stat (
    id integer NOT NULL,
    element_id_fk integer NOT NULL,
    sim_run_id_fk integer NOT NULL,
    stat_name character varying(510),
    stat_count double precision,
    average double precision,
    std_dev double precision,
    std_err double precision,
    half_width double precision,
    conf_level double precision,
    minimum double precision,
    maximum double precision,
    sum_of_obs double precision,
    dev_ssq double precision,
    last_value double precision,
    kurtosis double precision,
    skewness double precision,
    lag1_cov double precision,
    lag1_corr double precision,
    von_neumann_lag1_stat double precision,
    num_missing_obs double precision,
    CONSTRAINT across_rep_stat_half_width_check CHECK ((half_width >= (0)::double precision)),
    CONSTRAINT across_rep_stat_stat_count_check CHECK ((stat_count >= (0)::double precision)),
    CONSTRAINT across_rep_stat_std_dev_check CHECK ((std_dev >= (0)::double precision)),
    CONSTRAINT across_rep_stat_std_err_check CHECK ((std_err >= (0)::double precision))
);


--
-- Name: across_rep_stat_id_seq; Type: SEQUENCE; Schema: ksl_db; Owner: -
--

ALTER TABLE ksl_db.across_rep_stat ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME ksl_db.across_rep_stat_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: experiment; Type: TABLE; Schema: ksl_db; Owner: -
--

CREATE TABLE ksl_db.experiment (
    exp_id integer NOT NULL,
    sim_name character varying(510) NOT NULL,
    model_name character varying(510) NOT NULL,
    exp_name character varying(510) NOT NULL,
    num_chunks integer NOT NULL,
    length_of_rep double precision,
    length_of_warm_up double precision,
    rep_allowed_exec_time bigint,
    rep_init_option boolean NOT NULL,
    reset_start_stream_option boolean NOT NULL,
    antithetic_option boolean NOT NULL,
    adv_next_sub_stream_option boolean NOT NULL,
    num_stream_advances integer NOT NULL,
    gc_after_rep_option boolean NOT NULL
);


--
-- Name: model_element; Type: TABLE; Schema: ksl_db; Owner: -
--

CREATE TABLE ksl_db.model_element (
    exp_id_fk integer NOT NULL,
    element_id integer NOT NULL,
    element_name character varying(510) NOT NULL,
    class_name character varying(510) NOT NULL,
    parent_id_fk integer,
    parent_name character varying(510),
    left_count integer NOT NULL,
    right_count integer NOT NULL,
    CONSTRAINT model_element_left_count_check CHECK ((left_count > 0)),
    CONSTRAINT model_element_right_count_check CHECK ((right_count > 1)),
    CONSTRAINT traversal_order_okay CHECK ((left_count < right_count))
);


--
-- Name: simulation_run; Type: TABLE; Schema: ksl_db; Owner: -
--

CREATE TABLE ksl_db.simulation_run (
    run_id integer NOT NULL,
    exp_id_fk integer NOT NULL,
    run_name character varying(510) NOT NULL,
    num_reps integer NOT NULL,
    start_rep_id integer NOT NULL,
    last_rep_id integer,
    run_start_time_stamp bigint,
    run_end_time_stamp bigint,
    run_error_msg character varying(510),
    CONSTRAINT simulation_run_last_rep_id_check CHECK ((1 <= last_rep_id)),
    CONSTRAINT simulation_run_num_reps_check CHECK ((num_reps >= 1)),
    CONSTRAINT simulation_run_start_rep_id_check CHECK ((1 <= start_rep_id))
);


--
-- Name: across_rep_view; Type: VIEW; Schema: ksl_db; Owner: -
--

CREATE VIEW ksl_db.across_rep_view AS
 SELECT experiment.exp_name,
    across_rep_stat.stat_name,
    across_rep_stat.stat_count,
    across_rep_stat.average,
    across_rep_stat.std_dev
   FROM ksl_db.experiment,
    ksl_db.simulation_run,
    ksl_db.across_rep_stat,
    ksl_db.model_element
  WHERE ((experiment.num_chunks = 1) AND (experiment.exp_id = simulation_run.exp_id_fk) AND (simulation_run.run_id = across_rep_stat.sim_run_id_fk) AND (experiment.exp_id = model_element.exp_id_fk) AND (model_element.element_id = across_rep_stat.element_id_fk) AND ((model_element.element_name)::text = (across_rep_stat.stat_name)::text))
  ORDER BY experiment.exp_name, across_rep_stat.stat_name;


--
-- Name: batch_stat; Type: TABLE; Schema: ksl_db; Owner: -
--

CREATE TABLE ksl_db.batch_stat (
    id integer NOT NULL,
    element_id_fk integer NOT NULL,
    sim_run_id_fk integer NOT NULL,
    rep_id integer NOT NULL,
    stat_name character varying(510),
    stat_count double precision,
    average double precision,
    std_dev double precision,
    std_err double precision,
    half_width double precision,
    conf_level double precision,
    minimum double precision,
    maximum double precision,
    sum_of_obs double precision,
    dev_ssq double precision,
    last_value double precision,
    kurtosis double precision,
    skewness double precision,
    lag1_cov double precision,
    lag1_corr double precision,
    von_neumann_lag1_stat double precision,
    num_missing_obs double precision,
    min_batch_size double precision,
    min_num_batches double precision,
    max_num_batches_multiple double precision,
    max_num_batches double precision,
    num_rebatches double precision,
    current_batch_size double precision,
    amt_unbatched double precision,
    total_num_obs double precision,
    CONSTRAINT batch_stat_half_width_check CHECK ((half_width >= (0)::double precision)),
    CONSTRAINT batch_stat_rep_id_check CHECK ((rep_id >= 1)),
    CONSTRAINT batch_stat_stat_count_check CHECK ((stat_count >= (0)::double precision)),
    CONSTRAINT batch_stat_std_dev_check CHECK ((std_dev >= (0)::double precision)),
    CONSTRAINT batch_stat_std_err_check CHECK ((std_err >= (0)::double precision))
);


