--
-- Name: batch_stat_view; Type: VIEW; Schema: ksl_db; Owner: -
--

CREATE VIEW ksl_db.batch_stat_view AS
 SELECT experiment.exp_name,
    simulation_run.run_name,
    batch_stat.rep_id,
    batch_stat.stat_name,
    batch_stat.stat_count,
    batch_stat.average,
    batch_stat.std_dev
   FROM ksl_db.experiment,
    ksl_db.simulation_run,
    ksl_db.batch_stat,
    ksl_db.model_element
  WHERE ((experiment.exp_id = simulation_run.exp_id_fk) AND (simulation_run.run_id = batch_stat.sim_run_id_fk) AND (experiment.exp_id = model_element.exp_id_fk) AND (model_element.element_id = batch_stat.element_id_fk) AND ((model_element.element_name)::text = (batch_stat.stat_name)::text))
  ORDER BY experiment.exp_name, simulation_run.run_name, batch_stat.rep_id, batch_stat.stat_name;


