--
-- Name: within_rep_counter_view; Type: VIEW; Schema: ksl_db; Owner: -
--

CREATE VIEW ksl_db.within_rep_counter_view AS
 SELECT experiment.exp_name,
    simulation_run.run_name,
    simulation_run.num_reps,
    simulation_run.start_rep_id,
    simulation_run.last_rep_id,
    within_rep_counter_stat.stat_name,
    within_rep_counter_stat.rep_id,
    within_rep_counter_stat.last_value
   FROM ksl_db.experiment,
    ksl_db.simulation_run,
    ksl_db.within_rep_counter_stat,
    ksl_db.model_element
  WHERE ((experiment.exp_id = simulation_run.exp_id_fk) AND (simulation_run.run_id = within_rep_counter_stat.sim_run_id_fk) AND (experiment.exp_id = model_element.exp_id_fk) AND (model_element.element_id = within_rep_counter_stat.element_id_fk) AND ((model_element.element_name)::text = (within_rep_counter_stat.stat_name)::text))
  ORDER BY experiment.exp_name, within_rep_counter_stat.stat_name, within_rep_counter_stat.rep_id;


--
-- Name: within_rep_stat; Type: TABLE; Schema: ksl_db; Owner: -
--

CREATE TABLE ksl_db.within_rep_stat (
    id integer NOT NULL,
    element_id_fk integer NOT NULL,
    sim_run_id_fk integer NOT NULL,
    rep_id integer NOT NULL,
    stat_name character varying(510),
    stat_count double precision,
    average double precision,
    minimum double precision,
    maximum double precision,
    weighted_sum double precision,
    sum_of_weights double precision,
    weighted_ssq double precision,
    last_value double precision,
    last_weight double precision,
    CONSTRAINT within_rep_stat_rep_id_check CHECK ((rep_id >= 1)),
    CONSTRAINT within_rep_stat_stat_count_check CHECK ((stat_count >= (0)::double precision))
);


--
-- Name: within_rep_response_view; Type: VIEW; Schema: ksl_db; Owner: -
--

CREATE VIEW ksl_db.within_rep_response_view AS
 SELECT experiment.exp_name,
    simulation_run.run_name,
    simulation_run.num_reps,
    simulation_run.start_rep_id,
    simulation_run.last_rep_id,
    within_rep_stat.stat_name,
    within_rep_stat.rep_id,
    within_rep_stat.average
   FROM ksl_db.experiment,
    ksl_db.simulation_run,
    ksl_db.model_element,
    ksl_db.within_rep_stat
  WHERE ((experiment.exp_id = simulation_run.exp_id_fk) AND (simulation_run.run_id = within_rep_stat.sim_run_id_fk) AND (experiment.exp_id = model_element.exp_id_fk) AND (model_element.element_id = within_rep_stat.element_id_fk) AND ((model_element.element_name)::text = (within_rep_stat.stat_name)::text))
  ORDER BY experiment.exp_name, within_rep_stat.stat_name, within_rep_stat.rep_id;


--
-- Name: within_rep_view; Type: VIEW; Schema: ksl_db; Owner: -
--

CREATE VIEW ksl_db.within_rep_view AS
 SELECT within_rep_response_view.exp_name,
    within_rep_response_view.run_name,
    within_rep_response_view.num_reps,
    within_rep_response_view.start_rep_id,
    within_rep_response_view.last_rep_id,
    within_rep_response_view.stat_name,
    within_rep_response_view.rep_id,
    within_rep_response_view.average AS rep_value
   FROM ksl_db.within_rep_response_view
UNION
 SELECT within_rep_counter_view.exp_name,
    within_rep_counter_view.run_name,
    within_rep_counter_view.num_reps,
    within_rep_counter_view.start_rep_id,
    within_rep_counter_view.last_rep_id,
    within_rep_counter_view.stat_name,
    within_rep_counter_view.rep_id,
    within_rep_counter_view.last_value AS rep_value
   FROM ksl_db.within_rep_counter_view
  ORDER BY 1, 6, 7;


