--
-- Name: pw_diff_within_rep_view; Type: VIEW; Schema: ksl_db; Owner: -
--

CREATE VIEW ksl_db.pw_diff_within_rep_view AS
 SELECT ea.sim_name,
    a.stat_name,
    a.rep_id,
    a.exp_name AS a_exp_name,
    a.rep_value AS a_value,
    b.exp_name AS b_exp_name,
    b.rep_value AS b_value,
    (((('('::text || (a.exp_name)::text) || ' - '::text) || (b.exp_name)::text) || ')'::text) AS diff_name,
    (a.rep_value - b.rep_value) AS a_minus_b
   FROM ksl_db.within_rep_view a,
    ksl_db.within_rep_view b,
    ksl_db.experiment ea,
    ksl_db.experiment eb
  WHERE (((ea.exp_name)::text = (a.exp_name)::text) AND ((eb.exp_name)::text = (b.exp_name)::text) AND (a.num_reps = b.num_reps) AND ((a.stat_name)::text = (b.stat_name)::text) AND (a.rep_id = b.rep_id) AND (ea.exp_id > eb.exp_id));


