--
-- Name: time_series_response; Type: TABLE; Schema: ksl_db; Owner: -
--

CREATE TABLE ksl_db.time_series_response (
    id integer NOT NULL,
    element_id_fk integer NOT NULL,
    sim_run_id_fk integer NOT NULL,
    rep_id integer NOT NULL,
    stat_name character varying(510),
    period integer NOT NULL,
    start_time double precision,
    end_time double precision,
    length double precision,
    value double precision,
    CONSTRAINT time_series_response_end_time_check CHECK ((end_time > (0)::double precision)),
    CONSTRAINT time_series_response_length_check CHECK ((length > (0)::double precision)),
    CONSTRAINT time_series_response_period_check CHECK ((period >= 1)),
    CONSTRAINT time_series_response_rep_id_check CHECK ((rep_id >= 1)),
    CONSTRAINT time_series_response_start_time_check CHECK ((start_time >= (0)::double precision))
);


--
-- Name: time_series_response_across_rep_view; Type: VIEW; Schema: ksl_db; Owner: -
--

CREATE VIEW ksl_db.time_series_response_across_rep_view AS
 SELECT experiment.exp_name,
    time_series_response.element_id_fk,
    time_series_response.sim_run_id_fk,
    time_series_response.stat_name,
    time_series_response.period,
    time_series_response.start_time,
    time_series_response.end_time,
    count(time_series_response.value) AS "STAT_COUNT",
    avg(time_series_response.value) AS "AVERAGE",
    stddev_samp(time_series_response.value) AS "STD_DEV",
    min(time_series_response.value) AS "MINIMUM",
    max(time_series_response.value) AS "MAXIMUM"
   FROM ksl_db.time_series_response,
    ksl_db.experiment,
    ksl_db.simulation_run,
    ksl_db.model_element
  WHERE ((experiment.exp_id = simulation_run.exp_id_fk) AND (simulation_run.run_id = time_series_response.sim_run_id_fk) AND (experiment.exp_id = model_element.exp_id_fk) AND (model_element.element_id = time_series_response.element_id_fk) AND ((model_element.element_name)::text = (time_series_response.stat_name)::text))
  GROUP BY experiment.exp_name, time_series_response.element_id_fk, time_series_response.sim_run_id_fk, time_series_response.stat_name, time_series_response.period, time_series_response.start_time, time_series_response.end_time
  ORDER BY experiment.exp_name, time_series_response.element_id_fk, time_series_response.sim_run_id_fk, time_series_response.stat_name, time_series_response.period, time_series_response.start_time, time_series_response.end_time;


